T.set('prs-inner', { filter: 'blur(0px)' }, O2);
reveal('prs-head', O2 + 0.5);
reveal('prs-head2', O2 + 0.5);
T.to('prs-tab0', { textColor: '#1f2328', duration: .05 }, O2 + 0.25);
