for (var i = 0; i < 6; i++) {
  T.fromTo('prs-r' + (i + 1), { opacity: 0, x: 16 }, { opacity: 1, x: 0, duration: .18, ease: 'power2.out' }, O2 + 0.3 + i * 0.12);
}
T.to('prs-review', { opacity: 0, duration: .2 }, O2 + 1.1);
T.to('prs-files', { opacity: 1, duration: .2 }, O2 + 1.15);
T.to('prs-inner', { y: -3600, duration: 1.7, ease: 'power2.in' }, O2 + 1.2);
T.fromTo('prs-inner', { filter: 'blur(0px)' }, { filter: 'blur(2px)', duration: 1.1, ease: 'power2.in' }, O2 + 1.5);
reveal('prs-s1', O2 + 1.2); T.set('prs-cr1', { opacity: 1 }, O2 + 1.35); tw('prs-files-n', "629", O2 + 1.35, .45, 'none');
reveal('prs-s2', O2 + 1.75); T.set('prs-cr2', { opacity: 1 }, O2 + 1.9); tw('prs-lines-n', "87,291", O2 + 1.9, .7, 'none');
reveal('prs-s3', O2 + 2.35); T.set('prs-cr3', { opacity: 1 }, O2 + 2.5); tw('prs-commits-n', "4", O2 + 2.5, .2, 'none');
T.to('prs-cr1', { opacity: 0, duration: .25, ease: 'steps(1)', repeat: 1, yoyo: true }, O2 + 1.35 + .45);
T.to('prs-cr2', { opacity: 0, duration: .25, ease: 'steps(1)', repeat: 1, yoyo: true }, O2 + 1.9 + .7);
T.to('prs-cr3', { opacity: 0, duration: .25, ease: 'steps(1)', repeat: 1, yoyo: true }, O2 + 2.5 + .2);

/* ════════════ SCENE 3 — hard-read ════════════ */
T.fromTo('hr-txt', { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: .28, ease: 'power3.out' }, O3);

/* ════════════ SCENE 4 — summarize ════════════ */
