T.set('sm-caret', { opacity: 0 }, O4 + 0.82);
T.to('sm-composer', { y: -44, opacity: 0, duration: .32, ease: 'power2.in' }, O4 + 0.85);
T.to('sm-feed', { opacity: 1, duration: .25, ease: 'power1.out' }, O4 + 0.92);
T.fromTo('sm-inner', { y: 0 }, { y: -2400, duration: 1.25, ease: 'power1.in' }, O4 + 1.0);
T.to('sm-veil', { opacity: 1, duration: .3, ease: 'power2.in' }, O4 + 2.2);
T.fromTo('sm-still', { opacity: 0, y: 14 }, { opacity: 1, y: 0, duration: .32, ease: 'power3.out' }, O4 + 2.32);

/* ════════════ SCENE 5 — use-skill ════════════ */
T.set('us-stack', { y: 180 }, 0);
T.to('us-orb', { rotation: 360, duration: 1, ease: 'none', repeat: 3 }, O5);
T.to('us-caret', { opacity: 0, duration: .5, ease: 'steps(1)', repeat: 1, yoyo: true }, O5 + 0.1);
T.set('us-ph', { opacity: 0 }, O5 + 0.4);
T.set('us-caret', { opacity: 1 }, O5 + 0.4);
tw('us-typed', "use pr-to-video to make a video for this pr", O5 + 0.4, 1.4, 'none');
T.set('us-caret', { opacity: 0 }, O5 + 2.0);
T.fromTo('us-cmd', { opacity: 0 }, { opacity: 1, duration: .3, ease: 'power2.out' }, O5 + 2.05);
T.to('us-stack', { y: 90, duration: .4, ease: 'power3.out' }, O5 + 2.05);
T.fromTo('us-out', { opacity: 0 }, { opacity: 1, duration: .2 }, O5 + 2.45);
T.to('us-stack', { y: 0, duration: .4, ease: 'power3.out' }, O5 + 2.5);
T.fromTo('us-think', { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: .3, ease: 'power2.out' }, O5 + 2.5);
T.to('us-ast', { rotation: 360, duration: 1.0, ease: 'none', repeat: 1 }, O5 + 2.5);
T.fromTo('us-l0', { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: .35, ease: 'power3.out' }, O5 + 3.0);

/* ════════════ SCENES 6–9 — feature cards (compressed inner time) ════════════ */
function cardTitle(id, caret, title, off, dur, signed) {
  tw(id, title, off + 0.3 / signed, dur / signed, 'none');
  T.to(caret, { opacity: 0, duration: .4, ease: 'steps(1)', repeat: 9, yoyo: true }, off + 0.3 / signed);
  T.to(caret, { opacity: 0, duration: .3, ease: 'power2.in' }, off + 4.5 / signed);
}
// feature-code (timeScale 2.0)
cardTitle('fc-ttext', 'fc-tcaret', "SHOW YOUR CODE", O6, 1.15, 2.0);
T.fromTo('fc-pwin', { opacity: 0, scale: .62, y: 10 }, { opacity: 1, scale: 1, y: 0, duration: .6 / 2, ease: 'power3.out' }, O6 + 0.15 / 2);
T.to('fc-codeview', { opacity: 1, duration: .45 / 2, ease: 'power2.out' }, O6 + 1.0 / 2);
T.to('fc-pfill', { scaleX: .11, duration: 3.2 / 2, ease: 'none' }, O6 + 1.4 / 2);
T.to('fc-pknob', { left: 11, duration: 3.2 / 2, ease: 'none' }, O6 + 1.4 / 2);
T.to('fc-nonkeyA', { opacity: .32, duration: .4 / 2, ease: 'power2.out' }, O6 + 2.45 / 2);
T.to('fc-nonkeyB', { opacity: .32, duration: .4 / 2, ease: 'power2.out' }, O6 + 2.45 / 2);
