cardTitle('ff-ttext', 'ff-tcaret', "SHOW YOUR FEATURE", O7, 1.15, 2.56);
T.fromTo('ff-pwin', { opacity: 0, scale: .62, y: 10 }, { opacity: 1, scale: 1, y: 0, duration: .6 / 2.56, ease: 'power3.out' }, O7 + 0.15 / 2.56);
