T.to('ff-pknob', { left: 42, duration: 3.6 / 2.56, ease: 'none' }, O7 + 1.9 / 2.56);
T.fromTo('ff-diff', { opacity: 0, x: -30, scale: .95 }, { opacity: 1, x: 0, scale: 1, duration: .5 / 2.56, ease: 'power3.out' }, O7 + 2.0 / 2.56);
T.fromTo('ff-a1', { opacity: 0, x: -10 }, { opacity: 1, x: 0, duration: .35 / 2.56, ease: 'power2.out' }, O7 + 2.55 / 2.56);
for (var c = 1; c <= 5; c++) {
  T.to('#ff-fc' + c, { opacity: 1, y: 0, scale: 1, duration: .4 / 2.56, ease: 'back.out(1.6)' }, O7 + 2.7 / 2.56 + (c - 1) * (0.1 / 2.56));
}
T.to('ff-striplbl', { opacity: 1, duration: .4 / 2.56, ease: 'power2.out' }, O7 + 3.0 / 2.56);
T.fromTo('ff-a2', { opacity: 0, x: -10 }, { opacity: 1, x: 0, duration: .35 / 2.56, ease: 'power2.out' }, O7 + 3.45 / 2.56);
