  T.to(pairs[pi][0], { opacity: 0, duration: .2 / 4.1, ease: 'power2.in' }, pt);
  T.fromTo(pairs[pi][1], { opacity: 0, scale: .8 }, { opacity: 1, scale: 1, duration: .32 / 4.1, ease: 'back.out(1.7)' }, pt + .04 / 4.1);
}
T.to('fd-merge', { opacity: 1, scale: 1, y: 0, duration: .55 / 4.1, ease: 'back.out(1.6)' }, O8 + 5.9 / 4.1);
// feature-credits (2.54)
