/* ════════════ SCENE 10 — cta ════════════ */
T.set('cta-top', { scale: 1.18, y: 206, transformOrigin: '50% 50%', opacity: 0 }, 0);
T.set('cta-headrow', { x: 364.5 }, 0);
T.to('cta-orb', { rotation: 360, duration: 1, ease: 'none', repeat: 4 }, O10);
