T.set('cta-h2', { opacity: 1 }, O10 + 0.3 + 12 * (0.95 / 24));
T.set('cta-h3', { opacity: 1 }, O10 + 0.3 + 20 * (0.95 / 24));
T.to('cta-top', { scale: 1, y: 0, duration: .55, ease: 'power3.inOut' }, O10 + 1.5);
