tw('cta-cmd', "use pr-to-video ", O10 + 2.2, 0.55, 'none');
// reference sets url.textContent instantly at 2.85. Insert the text AT that
// time (not at eval) so the dom node is empty until then — otherwise its full
// width occupies layout from t=0 and shoves the caret + placeholder to the
// centre of the bar (ref keeps them left-aligned until the URL appears).
T.set('cta-url', { opacity: 0 }, 0);
T.set({ set: function(){ ctx.getNode('cta-url').text("https://github.com/your-org/your-repo/pull/42"); } }, { opacity: 1 }, O10 + 2.85);
T.fromTo('cta-url', { scale: 1.07 }, { scale: 1, duration: .3, ease: 'power3.out', transformOrigin: '0% 50%' }, O10 + 2.85);
T.to('cta-caret', { opacity: 0, duration: .4, ease: 'steps(1)', repeat: 5, yoyo: true }, O10 + 3.15);
T.to('cta-ret', { color: '#D97757', scale: 1.18, duration: .16, ease: 'back.out(2)', transformOrigin: '50% 50%' }, O10 + 3.25);
T.to('cta-ret', { scale: 1, duration: .28, ease: 'power2.out' }, O10 + 3.42);
